"""The fault code library shipped in the app (generated by tools/make_code_library.py)."""

import json
import os
import re
import sys
import unittest

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))

import make_code_library as lib  # noqa: E402

JSON_PATH = os.path.join(ROOT, "ios-app", "BMWLinkKit", "Sources", "BMWLinkKit", "Resources",
                         "code-library.json")
SAE = re.compile(r"^[PCBU][0-3][0-9A-F]{3}$")


class CodeLibraryTests(unittest.TestCase):
    def setUp(self):
        with open(JSON_PATH, encoding="utf-8") as f:
            self.text = f.read()
        self.data = json.loads(self.text)
        self.codes = self.data["codes"]

    def test_committed_json_is_up_to_date(self):
        self.assertEqual(self.text, lib.render(),
                         "run: python3 tools/make_code_library.py")

    def test_codes_are_sae_unique_and_sorted(self):
        names = [c["code"] for c in self.codes]
        self.assertEqual(names, sorted(set(names)))
        for n in names:
            self.assertRegex(n, SAE)

    def test_every_entry_is_complete(self):
        for c in self.codes:
            with self.subTest(c["code"]):
                self.assertIn(c["severity"], lib.SEVERITIES)
                for key in ("title", "system", "meaning", "drive"):
                    self.assertTrue(c[key].strip(), key)
                    self.assertEqual(c[key], c[key].strip())
                for key in ("meaning", "drive", "ignored"):
                    if key in c:
                        self.assertTrue(c[key].endswith("."), f"{key} should be a sentence")
                self.assertTrue(c["causes"] and c["checks"])
                for item in c["causes"] + c["checks"]:
                    self.assertTrue(item and not item.endswith("."), item)
                    self.assertEqual(item, item.strip())

    def test_common_codes_present(self):
        names = {c["code"] for c in self.codes}
        for n in ["P0171", "P0300", "P0301", "P0306", "P0351", "P0420", "P0299", "P0562",
                  "P0217", "P0524", "U0100", "P0136", "P0141"]:
            self.assertIn(n, names)
        self.assertNotIn("P013A", names)   # SAE numbering is decimal-style

    def test_stop_codes_say_stop(self):
        for c in self.codes:
            if c["severity"] == "stop":
                self.assertIn("Stop", c["drive"])


if __name__ == "__main__":
    unittest.main()
